insert into public.security_permissions(codigo,modulo,nome,criticidade) values ('vacation.read','ferias','Consultar férias','sensivel'),('vacation.manage','ferias','Gerenciar férias','critica') on conflict(codigo) do update set nome=excluded.nome;
insert into public.security_role_permissions(role_id,permission_id) select r.id,p.id from public.security_roles r join public.security_permissions p on p.codigo in('vacation.read','vacation.manage') where r.codigo='tenant_admin' on conflict do nothing;
insert into public.security_role_permissions(role_id,permission_id) select r.id,p.id from public.security_roles r join public.security_permissions p on p.codigo='vacation.read' where r.codigo in('sector_manager','auditor') on conflict do nothing;
create table public.vacation_policies(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),name text not null,accrual_months int not null default 12,entitlement_days int not null default 30,max_fractions int not null default 3,min_fraction_days int not null default 5,bonus_rate numeric(7,4) not null default .333333,effective_from date not null,effective_to date,check(max_fractions between 1 and 3),check(entitlement_days>0),unique(tenant_id,name,effective_from));
create table public.vacation_accrual_periods(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),employment_link_id uuid not null references public.employment_links(id),policy_id uuid not null references public.vacation_policies(id),accrual_start date not null,accrual_end date not null,concession_deadline date not null,entitled_days int not null,taken_days int not null default 0,status text not null default 'disponivel',check(accrual_end>=accrual_start),check(taken_days between 0 and entitled_days),check(status in('em_aquisicao','disponivel','programado','em_gozo','gozado','vencido')),unique(employment_link_id,accrual_start,accrual_end));
create table public.vacation_schedules(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),accrual_period_id uuid not null references public.vacation_accrual_periods(id),start_date date not null,end_date date not null,days int not null,status text not null default 'programado',base_amount numeric(14,2) not null,bonus_amount numeric(14,2) not null,total_amount numeric(14,2) not null,payment_date date not null,memory jsonb not null,created_by uuid references public.profiles(id),created_at timestamptz default now(),check(end_date>=start_date),check(days>0),check(status in('programado','aprovado','pago','em_gozo','concluido','cancelado')),check(payment_date<start_date),check(total_amount=base_amount+bonus_amount));
create or replace function public.validate_vacation_schedule() returns trigger language plpgsql set search_path=public as $$ declare p record; begin select a.*,l.tenant_id link_tenant into p from public.vacation_accrual_periods a join public.employment_links l on l.id=a.employment_link_id where a.id=new.accrual_period_id; if p.id is null or p.tenant_id<>new.tenant_id or p.link_tenant<>new.tenant_id then raise exception 'Férias contêm referência de outra entidade'; end if; if (select count(*) from public.vacation_schedules s where s.accrual_period_id=new.accrual_period_id and s.id<>new.id and s.status<>'cancelado')>=3 then raise exception 'Férias não podem exceder três frações'; end if; if (select coalesce(sum(days),0) from public.vacation_schedules s where s.accrual_period_id=new.accrual_period_id and s.id<>new.id and s.status<>'cancelado')+new.days>p.entitled_days then raise exception 'Saldo de dias insuficiente'; end if; if exists(select 1 from public.vacation_schedules s where s.accrual_period_id=new.accrual_period_id and s.id<>new.id and s.status<>'cancelado' and daterange(s.start_date,s.end_date+1,'[)')&&daterange(new.start_date,new.end_date+1,'[)')) then raise exception 'Frações de férias sobrepostas'; end if; return new; end $$;
create trigger trg_validate_vacation before insert or update on public.vacation_schedules for each row execute function public.validate_vacation_schedule();
alter table public.vacation_policies enable row level security;alter table public.vacation_accrual_periods enable row level security;alter table public.vacation_schedules enable row level security;
do $$ begin if to_regnamespace('auth') is not null then create policy vacation_policy_read on public.vacation_policies for select to authenticated using(private.has_tenant_permission(tenant_id,'vacation.read'));create policy vacation_policy_manage on public.vacation_policies for all to authenticated using(private.has_tenant_permission(tenant_id,'vacation.manage')) with check(private.has_tenant_permission(tenant_id,'vacation.manage'));create policy vacation_period_read on public.vacation_accrual_periods for select to authenticated using(private.has_tenant_permission(tenant_id,'vacation.read'));create policy vacation_period_manage on public.vacation_accrual_periods for all to authenticated using(private.has_tenant_permission(tenant_id,'vacation.manage')) with check(private.has_tenant_permission(tenant_id,'vacation.manage'));create policy vacation_schedule_read on public.vacation_schedules for select to authenticated using(private.has_tenant_permission(tenant_id,'vacation.read'));create policy vacation_schedule_manage on public.vacation_schedules for all to authenticated using(private.has_tenant_permission(tenant_id,'vacation.manage')) with check(private.has_tenant_permission(tenant_id,'vacation.manage'));end if;end $$;
revoke all on public.vacation_policies,public.vacation_accrual_periods,public.vacation_schedules from anon;do $$ begin if exists(select 1 from pg_roles where rolname='authenticated') then grant select,insert,update on public.vacation_policies,public.vacation_accrual_periods,public.vacation_schedules to authenticated;end if;end $$;commit;
